Show R Code
library(tidyverse)

# Load the Kaggle Olympic dataset (271,116 rows and 15 columns)
olympics &lt;- read_csv("data/athlete_events.csv", show_col_types = FALSE)

# Count one medal per unique event and NOC to avoid overcounting team sports
medals_unique &lt;- olympics |&gt;
  filter(!is.na(Medal)) |&gt;
  distinct(Year, Season, Games, Sport, Event, NOC, Medal)

# All Summer Olympic Games in which Spain (ESP) participated (1900–2016)
spain_summer_games &lt;- olympics |&gt;
  filter(NOC == "ESP", Season == "Summer") |&gt;
  distinct(Year, Games, City) |&gt;
  arrange(Year)

# Count Spain's unique Summer event medals by Olympic year (including 0-medal participations)
spain_summer_timeline &lt;- spain_summer_games |&gt;
  left_join(
    medals_unique |&gt;
      filter(NOC == "ESP", Season == "Summer") |&gt;
      group_by(Year) |&gt;
      summarise(
        Total_Medals = n(),
        Gold = sum(Medal == "Gold"),
        Silver = sum(Medal == "Silver"),
        Bronze = sum(Medal == "Bronze"),
        .groups = "drop"
      ),
    by = "Year"
  ) |&gt;
  mutate(
    across(c(Total_Medals, Gold, Silver, Bronze), \(x) replace_na(x, 0L)),
    Era = case_when(
      Year &lt; 1992 ~ "Before 1992 (1900–1988)",
      Year == 1992 ~ "Barcelona 1992 (Host Year)",
      Year &gt; 1992 ~ "After 1992 (1996–2016)"
    ),
    Era = factor(
      Era,
      levels = c(
        "Before 1992 (1900–1988)",
        "Barcelona 1992 (Host Year)",
        "After 1992 (1996–2016)"
      )
    )
  )
